export function migrateCatalog(db) {
  if (db.prepare('SELECT version FROM schema_migrations WHERE version = 2').get()) return false;
  db.exec('CREATE TABLE product_prices (product_id TEXT PRIMARY KEY REFERENCES products(id), price_cents INTEGER NOT NULL CHECK (price_cents >= 0))');
  const insert = db.prepare('INSERT INTO product_prices(product_id, price_cents) VALUES (?, ?)');
  for (const row of db.prepare('SELECT id, price FROM products ORDER BY id').all()) {
    insert.run(row.id, Math.round(row.price * 100));
  }
  db.prepare('INSERT INTO schema_migrations(version) VALUES (?)').run(2);
  return true;
}

import assert from 'node:assert/strict';
import test from 'node:test';
import { DatabaseSync } from 'node:sqlite';
import { migrateCatalog } from '../src/catalog-migration.mjs';

function setup(prices = [12.5, 0, 99.99]) {
  const db = new DatabaseSync(':memory:');
  db.exec('PRAGMA foreign_keys = ON; CREATE TABLE products(id TEXT PRIMARY KEY, name TEXT NOT NULL, price REAL NOT NULL); CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY); INSERT INTO schema_migrations VALUES (1)');
  const insert = db.prepare('INSERT INTO products(id, name, price) VALUES (?, ?, ?)');
  prices.forEach((price, index) => insert.run('p' + index, 'Supplier product ' + index, price));
  return db;
}
function pricesTable(db) {
  return db.prepare("SELECT name FROM sqlite_master WHERE type = 'table' AND name = 'product_prices'").get();
}

test('migration converts historical decimal prices without changing source data', () => {
  const db = setup();
  try {
    const before = db.prepare('SELECT * FROM products ORDER BY id').all();
    assert.equal(migrateCatalog(db), true);
    assert.deepEqual(db.prepare('SELECT price_cents FROM product_prices ORDER BY product_id').all().map(row => row.price_cents), [1250, 0, 9999]);
    assert.deepEqual(db.prepare('SELECT * FROM products ORDER BY id').all(), before);
    assert.deepEqual(db.prepare('SELECT version FROM schema_migrations ORDER BY version').all().map(row => row.version), [1, 2]);
  } finally { db.close(); }
});

test('a bad later row rolls back DDL, earlier inserts, and version marker; corrected input can retry', () => {
  const db = setup([12.5, -2, 99.99]);
  try {
    const before = db.prepare('SELECT * FROM products ORDER BY id').all();
    assert.throws(() => migrateCatalog(db), /CHECK constraint failed/i);
    assert.equal(pricesTable(db), undefined, 'failed migration must not leave a created table or partial rows');
    assert.deepEqual(db.prepare('SELECT * FROM products ORDER BY id').all(), before);
    assert.deepEqual(db.prepare('SELECT version FROM schema_migrations ORDER BY version').all().map(row => row.version), [1]);
    db.prepare('UPDATE products SET price = ? WHERE id = ?').run(2, 'p1');
    assert.equal(migrateCatalog(db), true, 'transaction must be closed so retry is possible');
    assert.deepEqual(db.prepare('SELECT price_cents FROM product_prices ORDER BY product_id').all().map(row => row.price_cents), [1250, 200, 9999]);
  } finally { db.close(); }
});

test('a completed migration is idempotent and preserves later valid writes', () => {
  const db = setup();
  try {
    assert.equal(migrateCatalog(db), true);
    db.prepare('UPDATE product_prices SET price_cents = ? WHERE product_id = ?').run(1500, 'p0');
    assert.equal(migrateCatalog(db), false);
    assert.equal(db.prepare('SELECT price_cents FROM product_prices WHERE product_id = ?').get('p0').price_cents, 1500);
    assert.equal(db.prepare('SELECT COUNT(*) AS count FROM schema_migrations WHERE version = 2').get().count, 1);
  } finally { db.close(); }
});

test('empty catalogs migrate successfully and retain relational constraints', () => {
  const db = setup([]);
  try {
    assert.equal(migrateCatalog(db), true);
    assert.equal(db.prepare('SELECT COUNT(*) AS count FROM product_prices').get().count, 0);
    assert.throws(() => db.prepare('INSERT INTO product_prices VALUES (?, ?)').run('missing', 100), /FOREIGN KEY constraint failed/i);
  } finally { db.close(); }
});
